"use strict";var OW_GOODS=[{k:"ow_hg_graphite",n:"Mercury graphite",e:"🖤",b:7,w:"mercury",lo:1,hi:3,g:18,note:"The dark, low-reflectance rock MESSENGER found all over Mercury: much of its darkness is carbon, as graphite."},{k:"ow_hg_hollow",n:"Hollow-floor sulphur dust",e:"🟡",b:6,w:"mercury",lo:2,hi:4,g:15,note:"Scooped from the bright, shallow hollows where something in the rock, probably sulphur-rich, has boiled away."},{k:"ow_hg_cell",n:"Charged power cell",e:"🔋",b:9,w:"mercury",lo:1,hi:2,g:12,pool:"fuel",note:"Charged in sunlight seven times as strong as Earth's, at the Sun Field."},{k:"ow_ve_basalt",n:"Venus basalt core",e:"🪨",b:8,w:"venus",lo:1,hi:2,g:18,note:"Drilled by the robot rigs on the plains of Lavinia, dark volcanic rock like Earth's."},{k:"ow_ve_tessera",n:"Tessera rock sample",e:"🧱",b:10,w:"venus",lo:1,hi:2,g:20,note:"From the folded, crumpled highlands called tesserae, maybe the oldest ground on Venus."},{k:"ow_ve_salvage",n:"Heat-proof probe salvage",e:"⚙️",b:9,w:"venus",lo:1,hi:3,g:15,note:"Parts from landers the heat and pressure finished. Refined into machine parts at a trade post."},{k:"ow_pl_n2",n:"Nitrogen ice",e:"🧊",b:4,w:"pluto",lo:2,hi:5,g:12,note:"From the slowly churning glacier of Sputnik Planitia, at −230 °C."},{k:"ow_pl_water",n:"Water-ice bedrock",e:"🧊",b:5,w:"pluto",lo:1,hi:3,g:15,note:"So cold it is as hard as granite: Pluto's mountains are made of it. Melted, it is water."},{k:"ow_pl_tholin",n:"Tholin dust",e:"🟤",b:12,w:"pluto",lo:1,hi:2,g:25,note:"The red-brown stuff made when sunlight breaks up methane: it colours Pluto's dark regions."},{k:"ow_pl_methane",n:"Methane frost",e:"❄️",b:6,w:"pluto",lo:1,hi:3,g:15,note:"Bright frost that coats Pluto's high peaks like snow."},{k:"ow_h2",n:"Hydrogen canister",e:"🫧",b:4,w:"giants",lo:2,hi:4,g:10,x:["ow_he3",.12],note:"Drawn in by a cloud station's skimmer intakes: the giants are mostly hydrogen."},{k:"ow_he3",n:"Helium-3 canister",e:"✨",b:20,w:"giants",lo:1,hi:1,g:30,note:"A rare light helium. Scientists think it could one day fuel clean fusion power."},{k:"ow_ju_ammonia",n:"Ammonia ice crystals",e:"🤍",b:6,w:"jupiter",lo:2,hi:4,g:12,note:"Jupiter's white cloud tops are frozen ammonia."},{k:"ow_sa_ringice",n:"Ring ice",e:"💎",b:7,w:"saturn",lo:1,hi:3,g:15,note:"Water ice from Saturn's rings, brought in by the station's shuttle: some pieces dust, some the size of a house."},{k:"ow_ur_h2s",n:"Hydrogen sulphide frost",e:"🥚",b:6,w:"uranus",lo:1,hi:3,g:12,note:"From Uranus's cloud tops. It smells of rotten eggs, which telescopes worked out in 2018."},{k:"ow_ur_methane",n:"Methane canister",e:"🔵",b:6,w:"uranus",lo:2,hi:3,g:12,note:"The methane that soaks up red light and makes Uranus blue-green."},{k:"ow_ne_methane",n:"Methane ice crystals",e:"⚪",b:6,w:"neptune",lo:2,hi:3,g:12,note:"The white streaks over Neptune's blue are clouds of frozen methane."},{k:"ow_ne_storm",n:"Storm data core",e:"💾",b:11,w:"neptune",lo:1,hi:1,g:20,note:"A recorder from a weather balloon flown through the fastest winds in the Solar System."},{k:"cr_crystal",n:"Star crystal",e:"💠",b:10,w:"veyar",lo:1,hi:2,g:40,note:"Grows at the feet of the Veyari towers. The forges prize it."},{k:"ow_vy_glowfruit",n:"Glowfruit",e:"🍈",b:5,fd:18,dr:6,w:"veyar",lo:2,hi:3,g:20,note:"A soft fruit of the glowing groves, sweet as melon."},{k:"ow_vy_dew",n:"Dewbell nectar",e:"🔔",b:4,dr:22,w:"veyar",lo:1,hi:3,g:15,note:"The cool nectar dewbell flowers hold up to the two suns."},{k:"ow_vy_silk",n:"Veyari lightsilk",e:"🧣",b:30,pr:45,w:"veyar",note:"Woven by the Veyari from the threads of the groves. Only ever given in exchange."},{k:"ow_ar_potato",n:"Hydroponic potatoes",e:"🥔",b:3,fd:16,w:"ares",lo:2,hi:4,g:20,note:"Grown under lamps in the Gateway's hydroponics bay, in water, not soil."},{k:"ow_ar_greens",n:"Space lettuce",e:"🥬",b:2,fd:6,dr:4,w:"ares",lo:2,hi:4,g:15,note:"The first leaves astronauts ever ate grown in space were red romaine lettuce, on the ISS in 2015."},{k:"ow_ar_phobos",n:"Phobos regolith",e:"🌑",b:5,pr:8,w:"ares",note:"Dust from Mars's little moon Phobos, shipped in by the Gateway's ore barges."},{k:"ow_fuel",n:"Rocket fuel canister",e:"🛢️",b:14,w:"made",pool:"fuel",note:"Liquid hydrogen fuel, cracked and chilled from the giants' gas."},{k:"ow_water",n:"Melted ice water",e:"💧",b:2,dr:26,w:"made",note:"Ice melted and filtered: drinkable, and clean."},{k:"ow_ration",n:"Space Corp ration pack",e:"🥫",b:3,fd:30,pr:6,w:"supply",note:"A sealed meal: stew, bread you can eat without crumbs, fruit bar."},{k:"ow_pouch",n:"Water pouch",e:"🧃",b:1,dr:30,pr:2,w:"supply",note:"Recycled water, cleaner than most tap water."},{k:"ow_soup",n:"Cloud lounge soup",e:"🍲",b:4,fd:24,dr:10,pr:7,w:"supply",note:"The cook's soup, served with the best view in the Solar System."},{k:"ow_cocoa",n:"Tombaugh hot cocoa",e:"☕",b:2,fd:4,dr:24,pr:3,w:"supply",note:"Hot cocoa at the edge of the Solar System."},{k:"ow_tk_cake",n:"Tullik spice cake",e:"🍰",b:4,fd:34,pr:9,w:"tullik",note:"Pip-Tullik's own baking. It fizzes faintly."},{k:"ow_tk_hum",n:"Humming rock",e:"🪨",b:30,pr:42,w:"tullik",note:"A small grey stone that hums a low note when held. Pip will not say where it is from."},{k:"ow_tk_map",n:"Tullik star map",e:"🗺️",b:22,pr:30,w:"tullik",note:"Drawn by a Tullik navigator on something like paper. The constellations are seen from somewhere else."}];var OW_REFINE=[{k:"melt_pl",n:"Melt water-ice bedrock into drinking water",need:{ow_pl_water:2},make:"ow_water",x:3,at:["pluto","fab"]},{k:"crack",n:"Crack hydrogen into rocket fuel",need:{ow_h2:3},make:"ow_fuel",x:1,at:["jupiter","saturn","uranus","neptune","fab"]},{k:"melt_ring",n:"Melt ring ice into drinking water",need:{ow_sa_ringice:1},make:"ow_water",x:2,at:["saturn","fab"]},{k:"salvage",n:"Rebuild probe salvage into machine parts",need:{ow_ve_salvage:3},make:"cr_parts",x:1,at:["venus","fab"]},{k:"cells",n:"Build power cells into machine parts",need:{ow_hg_cell:2,ow_hg_graphite:1},make:"cr_parts",x:1,at:["mercury","fab"]},{k:"phobos",n:"Smelt Phobos regolith into iron ore",need:{ow_ar_phobos:3},make:"cr_ore",x:1,at:["fab"]},{k:"glass",n:"Fuse hollow dust and graphite into glass",need:{ow_hg_hollow:3,ow_hg_graphite:1},make:"cr_glass",x:1,at:["mercury","fab"]},{k:"silk",n:"Cut Veyari lightsilk into canvas and cloth",need:{ow_vy_silk:1},make:"cr_cloth",x:6,at:["veyar","fab"]}];var OW_SWAPS=[{k:"he3_crystal",who:"tullik",give:{ow_he3:2},get:"cr_crystal",x:1,say:"Two helium-3 for a star crystal. Fair! Fair-ish. Fair."},{k:"tholin_map",who:"tullik",give:{ow_pl_tholin:3},get:"ow_tk_map",x:1,say:"Pluto dust! The best dust. A map for it."},{k:"storm_hum",who:"tullik",give:{ow_ne_storm:2},get:"ow_tk_hum",x:1,say:"Storm stories in a box. I love them. Take a humming rock."},{k:"potato_cake",who:"tullik",give:{ow_ar_potato:4},get:"ow_tk_cake",x:2,say:"Potatoes! Human food! Two cakes for four."},{k:"ringice_crystal",who:"tullik",give:{ow_sa_ringice:6},get:"cr_crystal",x:1,say:"Ring ice is very pretty. I collect pretty."},{k:"g_silk",who:"veyari",give:{ow_sa_ringice:2,ow_pl_n2:3},get:"ow_vy_silk",x:1,say:"Ice from the ringed world and from the small cold one. We will weave you light for them."},{k:"g_silk2",who:"veyari",give:{ow_he3:1,ow_hg_graphite:2},get:"ow_vy_silk",x:1,say:"The rare breath of a giant, and dark stone from the world nearest your sun. A fair gift."},{k:"g_crystal",who:"veyari",give:{ow_ne_storm:1},get:"cr_crystal",x:2,say:"The winds of the blue giant, kept in a box. We will listen to it for a long time. Take two crystals."},{k:"g_fruit",who:"veyari",give:{ow_ar_potato:2},get:"ow_vy_glowfruit",x:3,say:"Food grown under lamps, so far from your sun. Taste ours."},{k:"g_dew",who:"veyari",give:{ow_hg_cell:1},get:"ow_vy_dew",x:3,say:"Sunlight caught in a box. The dewbells understand."}];var OW_JOBS=[[3701,"Caloris station chief","mercury",14,1,false,[8,8],[["Run Caloris Station","desk",["Read the overnight log","Check the sunshade's struts","Set the day's sampling","Sign off the power report"]]]],[3702,"Mercury surface sampler","mercury",11,3,true,[7,8],[["Sample the hollows and the dark rock","station",["Suit check at the airlock","Walk the shade line to the site","Scoop and seal the sample","Log it at the ice lab"]]]],[3703,"Solar array technician","mercury",11,2,true,[6,8],[["Keep the Sun Field","station",["Wipe the dust off the panels","Swap the full cells","Check the cables for heat damage","Read the output to ops"]]]],[3704,"Caloris Exchange clerk","mercury",10,1,true,[8,8],[["Run the Exchange","desk",["Weigh in the samples","Pay the crew for them","Stock the ration shelves","Write up the book"]]]],[3710,"Venus rover controller","venus",12,2,true,[7,8],[["Drive VERA","desk",["Wake the rover","Plan the drive round the boulders","Send the commands and wait","Check the heat in its electronics"]]]],[3711,"Probe salvage technician","venus",11,2,true,[7,8],[["Salvage the old landers","station",["Cool your suit at the post","Unbolt the parts that survived","Bag them for the workshop","Test them on the bench"]]]],[3712,"Venus geologist","venus",12,1,true,[8,8],[["Study the plains","station",["Set the drill rig","Pull the basalt core","Log the tessera samples","Send the findings to orbit"]]]],[3720,"Tombaugh station chief","pluto",14,1,false,[8,8],[["Run Tombaugh Station","desk",["Read the overnight log","Check the heaters","Set the day's drilling","Sign off the report to the Spaceport"]]]],[3721,"Glaciologist","pluto",12,2,true,[8,8],[["Study the nitrogen glacier","station",["Mark the edges of a cell","Measure how far it moved","Sample the ice","Write it up in the glacier lab"]]]],[3722,"Ice driller","pluto",11,3,true,[7,8],[["Drill the water-ice bedrock","station",["Check the drill's bit","Drill and lift the core","Stack it in the store","Clear the frost off the rig"]]]],[3723,"Tombaugh Exchange clerk","pluto",10,1,true,[8,8],[["Run the Exchange and the cocoa bar","desk",["Weigh in the samples","Pay the crew for them","Heat the cocoa","Write up the book"]]]],[3730,"Galileo station manager","jupiter",14,1,false,[8,8],[["Run Cloud Station Galileo","desk",["Read the storm watch","Trim the station's buoyancy","Set the skimmer rota","Sign the log"]]]],[3731,"Galileo probe officer","jupiter",12,2,true,[8,8],[["Drop the atmosphere probes","station",["Check the probe's heat shield","Wait for the target to drift under","Release it","Log what it sends"]]]],[3732,"Galileo skimmer operator","jupiter",11,3,true,[6,8],[["Run the skimmer intakes","station",["Open the intake","Fill the canisters","Seal and label them","Stack them in the store"]]]],[3733,"Galileo lounge cook","jupiter",10,1,true,[6,8],[["Cook in the lounge","station",["Bake the morning bread","Make the soup","Serve the crew","Clean the galley"]]]],[3740,"Cassini station manager","saturn",14,1,false,[8,8],[["Run Cloud Station Cassini","desk",["Read the ring watch","Trim the station's buoyancy","Set the ice runs","Sign the log"]]]],[3741,"Cassini probe officer","saturn",12,2,true,[8,8],[["Drop the atmosphere probes","station",["Check the probe","Wait for the target","Release it","Log what it sends"]]]],[3742,"Ring ice hauler","saturn",11,3,true,[6,8],[["Bring in the ring ice","station",["Fly the shuttle out to the ring","Net the ice","Unload it to the hopper","Sort it by size"]]]],[3743,"Cassini lounge cook","saturn",10,1,true,[6,8],[["Cook in the lounge","station",["Bake the morning bread","Make the soup","Serve the crew","Clean the galley"]]]],[3750,"Herschel station manager","uranus",14,1,false,[8,8],[["Run Cloud Station Herschel","desk",["Read the overnight log","Trim the station's buoyancy","Set the skimmer rota","Sign the log"]]]],[3751,"Herschel probe officer","uranus",12,2,true,[8,8],[["Drop the atmosphere probes","station",["Check the probe","Wait for the target","Release it","Log what it sends"]]]],[3752,"Herschel skimmer operator","uranus",11,3,true,[6,8],[["Run the skimmer intakes","station",["Open the intake","Fill the canisters","Seal and label them","Stack them in the store"]]]],[3753,"Herschel lounge cook","uranus",10,1,true,[6,8],[["Cook in the lounge","station",["Bake the morning bread","Make the soup","Serve the crew","Clean the galley"]]]],[3760,"Le Verrier station manager","neptune",14,1,false,[8,8],[["Run Cloud Station Le Verrier","desk",["Read the wind watch","Trim the station's buoyancy","Set the balloon launches","Sign the log"]]]],[3761,"Le Verrier probe officer","neptune",12,2,true,[8,8],[["Drop the atmosphere probes","station",["Check the probe","Lead the target against the wind","Release it","Log what it sends"]]]],[3762,"Weather balloon launcher","neptune",11,2,true,[6,8],[["Launch the weather balloons","station",["Fill the balloon","Clip on the recorder","Let it go into the wind","Catch the data core when it comes back"]]]],[3763,"Le Verrier lounge cook","neptune",10,1,true,[6,8],[["Cook in the lounge","station",["Bake the morning bread","Make the soup","Serve the crew","Clean the galley"]]]],[3770,"Envoy to Veyar","veyar",15,1,false,[9,8],[["Keep the embassy","desk",["Read the Veyari messages","Answer them with care","Meet the visitors","Write to the Space Corp"]]]],[3771,"Veyari interpreter","veyar",12,2,true,[9,8],[["Interpret for visitors","station",["Greet the visitor at the embassy","Walk with them to the Veyari","Put their words into ours","Write down new words learned"]]]],[3772,"Crystal grove keeper","veyar",11,2,true,[8,8],[["Tend the crystal groves","station",["Walk the towers' feet","Clear the fallen shards","Gather what the Veyari offer","Record the growth"]]]],[3780,"Ares Gateway commander","ares",14,1,false,[8,8],[["Command the Gateway","desk",["Read the overnight log","Set the descent schedule","Meet the crew","Report to the Spaceport"]]]],[3781,"Descent controller","ares",12,2,true,[8,8],[["Bring the landers down","desk",["Check the weather on Mars","Set the entry angle","Watch the seven minutes","Confirm touchdown"]]]],[3782,"Fab shop engineer","ares",12,2,true,[8,8],[["Work the fab shop","station",["Warm up the printers","Fabricate the parts on order","Test them","Shelve them for collection"]]]],[3783,"Hydroponics grower","ares",10,2,true,[7,8],[["Grow the Gateway's food","station",["Check the nutrient water","Set the lamps","Pick what is ready","Plant the next tray"]]]],[3784,"Ares ore broker","ares",10,1,true,[8,8],[["Run the ore desk","desk",["Meet the ore barge","Weigh the Phobos regolith","Price it for the city","Write up the book"]]]],[3790,"Space Corp instructor","any",12,1,false,[9,8],[["Teach World Learning: The Outer Worlds","station",["Meet the learners at the station","Teach the lesson where it happens","Ask the questions","Stamp the record"]]]],[3791,"Tullik trade liaison","space",11,1,true,[9,8],[["Trade with the Tullik","station",["Hail the trader's ship","Agree the swaps","Check the goods","Log the trade"]]]]];var OW_LESSONS=[{k:"hg_heat",w:"mercury",at:"shade",title:"Hot days, frozen nights",real:"Mercury's ground reaches about 430 °C by day and falls to about −180 °C at night. From here the Sun looks about three times as wide as it does from Earth.",science:"Air works like a blanket: it holds the day's heat and spreads it round. Mercury has almost none, only a faint exosphere, so its heat pours away into space as soon as the Sun sets.",word:["Exosphere","a layer of atoms so thin they almost never bump into each other. It is all the air Mercury has."],tryit:"Stand in the sunshade's shadow, then step out into the sunlight: that is why the Corp built it.",quiz:[["Why do Mercury's nights get so cold?","It has almost no air to hold the heat","It is far from the Sun","Its nights last only an hour"],["About how hot is Mercury's ground by day?","About 430 °C","About 40 °C","About 4,300 °C"]]},{k:"hg_ice",w:"mercury",at:"icelab",title:"Ice on the planet nearest the Sun",real:"NASA's MESSENGER orbited Mercury from 2011 to 2015 and confirmed water ice in craters near its poles.",science:"Mercury's axis is almost upright, tilted less than a tenth of a degree, so the floors of some craters near the poles never see the Sun at all. They stay colder than −170 °C, and ice there can last for billions of years.",word:["Permanently shadowed region","a place, like a polar crater floor, that sunlight never reaches."],tryit:"Look at the ice core in the lab's cold case: the crawler brought it down from the north pole.",quiz:[["Why can ice last near Mercury's poles?","Some crater floors never see sunlight","The poles are far from the Sun","The ice is made of iron"],["Which spacecraft confirmed ice at Mercury's poles?","MESSENGER","Voyager 1","Hubble"]]},{k:"ve_greenhouse",w:"venus",at:"cooling",title:"The runaway greenhouse",real:"Venus is about 465 °C at the ground, hotter than Mercury, though it is nearly twice as far from the Sun. Its air is 96.5% carbon dioxide and presses down 92 times as hard as Earth's.",science:"Sunlight warms the ground, and the ground gives the heat off as infrared. Carbon dioxide traps infrared, so the heat cannot get out. On Venus this has run away: the more it warmed, the more gas it held, and the hotter it got.",word:["Greenhouse effect","gases in the air trapping heat that would otherwise escape to space."],tryit:"Read the thermometer mast by the bunker door: it says the same at noon and at midnight, all over the planet.",quiz:[["Why is Venus hotter than Mercury?","Its thick carbon dioxide air traps heat","It is closer to the Sun","Volcanoes are erupting everywhere"],["Venus's air pressure at the ground is about…","92 times Earth's","Half of Earth's","The same as Earth's"]]},{k:"ve_machines",w:"venus",at:"control",title:"Machines that survive Venus",real:"The Soviet lander Venera 13 survived 127 minutes on Venus in 1982. In 2016, NASA chips made of silicon carbide ran for 521 hours, almost 22 days, in a chamber that copied Venus's heat and pressure.",science:"Ordinary electronics fail above about 125 °C. Silicon carbide can take far more heat. Because a radio signal takes minutes to reach Earth and back, rovers must also look after themselves between commands: that is called autonomy.",word:["Teleoperation","driving a machine from far away, sending it commands and waiting for its replies."],tryit:"Sit at the rover desk and watch VERA's heat gauge: it is the only thing that matters out there.",quiz:[["How long did Venera 13 survive on Venus?","About two hours (127 minutes)","Ten years","Ten seconds"],["What kind of chips survived weeks in a Venus test chamber?","Silicon carbide chips","Ordinary phone chips","Paper circuits"]]},{k:"pl_glacier",w:"pluto",at:"glacier",title:"A heart of nitrogen ice",real:"New Horizons flew past Pluto on 14 July 2015 and found Sputnik Planitia: a plain of frozen nitrogen about 1,000 km across, broken into cells tens of kilometres wide.",science:"Pluto's interior is a little warmer than its surface. The warmer nitrogen ice rises slowly in the middle of each cell and sinks at the edges, like a pot of very thick soup. This is convection, and it keeps the plain young and smooth, with no craters.",word:["Convection","heat carried by a fluid moving: warm stuff rises, cooler stuff sinks."],tryit:"Walk out onto the pale plain and find the dark lines between the cells: those are where the ice sinks.",quiz:[["What is Pluto's great plain mostly made of?","Frozen nitrogen","Liquid water","Sand"],["What makes the pattern of cells on the plain?","Ice slowly rising and sinking (convection)","Wind blowing sand","Meteor craters"]]},{k:"pl_ninth",w:"pluto",at:"ops",title:"The ninth planet's story",real:"Clyde Tombaugh found Pluto in 1930 at the Lowell Observatory in Arizona. He was 24. In 2006 astronomers made a new rule for planets and called Pluto a dwarf planet. Somnucor still counts it as the ninth.",science:"Tombaugh photographed the same patch of sky on nights days apart and flicked between the two pictures. Stars stay put; anything that jumped had moved, so it had to be close, in our own Solar System.",word:["Blink comparator","a machine that flips quickly between two photographs so that anything that moved seems to jump."],tryit:"Look at the two star photos pinned in the ops room and find the dot that moved.",quiz:[["How did Tombaugh find Pluto?","By comparing photos taken days apart to see what moved","With a spacecraft","By hearing it on the radio"],["Why did astronomers call Pluto a dwarf planet in 2006?","It has not cleared other bodies from its orbit","It stopped moving","It is made of gas"]]},{k:"ju_spot",w:"jupiter",at:"telescope",title:"The Great Red Spot",real:"The Great Red Spot is a storm wider than the Earth. People have watched it without a break since at least 1831, and it has been slowly shrinking.",science:"It is an anticyclone, spinning round a high-pressure middle, with winds at its edge of more than 400 km/h. Nothing solid lies beneath to slow it down, which may be why it has lasted so long.",word:["Anticyclone","a great storm that turns round high pressure in the middle."],tryit:"Look through the telescope at the rail, west across the clouds: the red oval is the storm.",quiz:[["What is the Great Red Spot?","A giant storm","A volcano","A lake"],["How big is it compared with the Earth?","Wider than the Earth","The size of a city","Smaller than the Moon"]]},{k:"ju_probe",w:"jupiter",at:"probebay",title:"A planet with no ground",real:"On 7 December 1995 the Galileo probe fell into Jupiter's clouds. It sent back measurements for about 58 minutes before the heat and pressure ended it.",science:"Jupiter is about 90% hydrogen and 10% helium. The deeper you go, the thicker and hotter it gets, until the gas is squeezed into a liquid: there is no surface to land on at all.",word:["Atmospheric probe","a spacecraft built to fall through a planet's air, measuring it on the way down."],tryit:"Drop a probe from the bay yourself: Jupiter's pull is two and a half times Earth's, so it falls fast.",quiz:[["What happened to the Galileo probe in 1995?","It fell through Jupiter's clouds sending data for about an hour","It landed on solid ground","It bounced back to Earth"],["Jupiter is mostly made of…","Hydrogen and helium","Rock and iron","Water and salt"]]},{k:"sa_rings",w:"saturn",at:"telescope",title:"The rings",real:"Saturn's main rings stretch about 280,000 km across, yet in most places they are only about 10 metres thick. NASA's Cassini studied Saturn for 13 years and ended on 15 September 2017 by diving into Saturn on purpose.",science:"The rings are billions of pieces of water ice, from specks of dust to boulders the size of houses, each orbiting Saturn like a tiny moon. Cassini was sent into Saturn so that it could never crash into one of its moons and carry Earth germs there.",word:["Ring particle","one of the countless pieces of ice and rock that make up a planet's rings."],tryit:"Look up from the rail: the rings arch over the sky like a bridge.",quiz:[["Saturn's rings are mostly…","Water ice","Gas","Solid rock bands"],["How did the Cassini mission end?","It dived into Saturn on purpose in 2017","It landed on the rings","It is still orbiting"]]},{k:"sa_moons",w:"saturn",at:"lab",title:"Titan and Enceladus",real:"The Huygens probe landed on Saturn's moon Titan on 14 January 2005. Cassini found jets of water ice shooting from the south pole of the moon Enceladus. NASA's Dragonfly, a flying drone, is being built to explore Titan.",science:"Titan is so cold that methane and ethane are liquid: they fall as rain and fill lakes and seas. Enceladus hides a salty ocean under its ice, and the jets are that ocean spraying out through cracks.",word:["Cryovolcano","an ice volcano, which erupts water or other icy stuff instead of molten rock."],tryit:"Look at the two moons on the lab's globe, then find Titan in the sky: the orange one.",quiz:[["What fills Titan's lakes?","Liquid methane and ethane","Water","Lava"],["What did Cassini find shooting from Enceladus?","Jets of water ice from an ocean underneath","Fire","Sand"]]},{k:"ur_tilt",w:"uranus",at:"telescope",title:"The planet on its side",real:"Uranus is tipped about 98 degrees, right over onto its side. William Herschel found it in 1781: the first planet discovered with a telescope.",science:"As Uranus goes round the Sun, each pole points at the Sun for part of its 84-year orbit. So each pole gets about 42 years of daylight, then about 42 years of night. A giant collision long ago may have knocked it over.",word:["Axial tilt","how far a planet's spin is leaning compared with the path it takes round the Sun."],tryit:"Look through the telescope at the rail and find the faint rings: they circle Uranus top to bottom, not side to side.",quiz:[["How far is Uranus tipped over?","About 98 degrees, onto its side","Not at all","About 5 degrees"],["Who discovered Uranus in 1781?","William Herschel","Galileo","Isaac Newton"]]},{k:"ur_ice",w:"uranus",at:"lab",title:"Ice giants and rotten eggs",real:"In 2018 astronomers using the Gemini North telescope found hydrogen sulphide in Uranus's cloud tops: the gas that makes rotten eggs smell.",science:"Uranus and Neptune are ice giants: under their hydrogen and helium lie great amounts of water, ammonia and methane. Methane soaks up red light, so the sunlight that bounces back is blue-green. Laboratory experiments suggest that deep inside, the pressure may squeeze carbon into diamonds: an idea scientists are still testing.",word:["Ice giant","a giant planet made mostly of water, ammonia and methane, rather than mostly hydrogen and helium."],tryit:"Look at the frost sample in the lab's sealed jar. Be glad it is sealed.",quiz:[["What gives Uranus its blue-green colour?","Methane soaking up red light","Oceans of water","Blue rock"],["Its cloud tops contain a gas that smells like…","Rotten eggs (hydrogen sulphide)","Roses","Nothing at all"]]},{k:"ne_found",w:"neptune",at:"telescope",title:"Found by mathematics",real:"Uranus was not moving quite as it should. Urbain Le Verrier worked out where an unseen planet must be pulling it from, and on 23 September 1846 Johann Galle found Neptune within about a degree of that spot.",science:"Every mass pulls on every other. A small tug that changes a planet's path is called a perturbation, and by measuring it carefully you can work out the mass and place of whatever is doing the pulling.",word:["Perturbation","a small tug that changes the path of a planet or moon."],tryit:"Look through the telescope at the rail. Neptune was the first planet found by pen and paper before anyone looked.",quiz:[["How was Neptune first found?","Its place was worked out from how it pulled on Uranus","A spacecraft bumped into it","A sailor saw it"],["In what year was it found?","1846","1609","1969"]]},{k:"ne_wind",w:"neptune",at:"probebay",title:"The windiest planet",real:"Voyager 2, the only spacecraft ever to visit Neptune, flew past in 1989. It measured winds of about 2,000 km/h and saw a storm the size of Earth, the Great Dark Spot. When the Hubble Space Telescope looked in 1994, the storm was gone.",science:"Neptune gets very little sunlight, yet it gives off more heat than it receives: heat from inside drives its weather. With no ground to slow them, its winds blow faster than sound does on Earth.",word:["Supersonic","faster than the speed of sound."],tryit:"Drop a probe from the bay and watch the wind carry it: aim upwind to hit the target.",quiz:[["How fast are Neptune's fastest winds?","About 2,000 km/h","About 20 km/h","About 200,000 km/h"],["Which is the only spacecraft to have visited Neptune?","Voyager 2","Apollo 11","Cassini"]]},{k:"ar_edl",w:"ares",at:"descent",title:"Seven minutes of terror",real:"On 18 February 2021 the rover Perseverance landed in Jezero Crater. From the top of the air to the ground took about seven minutes: a heat shield, a supersonic parachute, rockets, and a sky crane that lowered it on cables.",science:"Mars's air is too thin to slow a lander enough with a parachute alone, but thick enough to burn it up without a heat shield. A radio signal took about 11 minutes to reach Earth that day, so the whole landing had to fly itself.",word:["EDL","entry, descent and landing: the seven minutes from the top of the air to the ground."],tryit:"Fly a landing yourself in the descent simulator.",quiz:[["Why must a Mars landing fly itself?","Radio signals take minutes to reach Earth","Pilots are not allowed","Mars has no air at all"],["What lowered Perseverance to the ground on cables?","A sky crane","A balloon","A ladder"]]},{k:"ar_moons",w:"ares",at:"window",title:"Phobos and Deimos",real:"Asaph Hall found Mars's two little moons in 1877. Phobos is about 22 km across and goes round Mars three times a day; Deimos is about 12 km across. Japan's MMX mission is planned to bring home a sample of Phobos.",science:"Phobos orbits so close that Mars's pull is slowly dragging it lower, by about 2 metres every hundred years. In perhaps 50 million years it will break up into a ring or crash into Mars.",word:["Tidal decay","an orbit slowly shrinking because of the pull between a moon and its planet."],tryit:"Find both moons from the great window: Phobos is the nearer, lumpier one.",quiz:[["What will happen to Phobos?","It is slowly falling towards Mars","It will fly off to Jupiter","It will grow bigger"],["Who discovered Mars's moons in 1877?","Asaph Hall","Galileo","Neil Armstrong"]]},{k:"vy_suns",w:"veyar",at:"song",title:"Two suns",real:"Many of the stars you see are really two stars orbiting each other. In 2011 the Kepler space telescope found Kepler-16b, a planet that goes round two stars at once.",science:"Two stars of different masses swing round a point between them, called the centre of mass. A planet far enough out can orbit the pair together, so it would see two suns rise and set.",word:["Circumbinary planet","a planet that orbits two stars."],tryit:"Watch the rose sun and the little blue one: on a real circumbinary world the shadows would come in pairs.",quiz:[["What is a planet that orbits two stars called?","A circumbinary planet","A dwarf planet","A comet"],["Which telescope found Kepler-16b in 2011?","The Kepler space telescope","Hubble","A telescope on the Moon"]]},{k:"vy_worlds",w:"veyar",at:"embassy",title:"Worlds round other stars",real:"In 1995 Michel Mayor and Didier Queloz found 51 Pegasi b, the first planet known round a Sun-like star; they shared the 2019 Nobel Prize in Physics for it. NASA's count of confirmed planets beyond the Solar System passed 6,000 in 2025.",science:"Most are found in two ways. A planet crossing in front of its star dims it a tiny bit: the transit method. A planet's pull makes its star wobble, shifting its light: the radial velocity method.",word:["Transit","a planet passing in front of its star, as seen from here."],tryit:"Ask the envoy how the Space Corp first learned of Veyar.",quiz:[["How does the transit method find planets?","It sees a tiny dip in a star's light as a planet passes in front","It listens for alien radio","It photographs footprints"],["The first planet found round a Sun-like star, in 1995, was…","51 Pegasi b","Pluto","Kepler-16b"]]}];var OW_PLACES={mercury:{name:"Mercury",post:"Caloris Station",col:"#E8C27A",hall:{x:96,z:0,w:36,d:26,door:"w",name:"Caloris Station",rooms:[["airlock","The airlock lobby",-18,-5,-8,5],["ops","The operations room",-8,-13,6,-1],["exchange","The Caloris Exchange",-8,1,6,13],["icelab","The ice lab",6,-13,18,-1],["mess","The mess",6,1,18,13],["bunks","Crew bunks",-18,-13,-8,-5,1],["power","The power room",-18,5,-8,13,1]],doors:[[-8,0],[-1,-1],[-1,1],[12,-1],[12,1],[-13,-5,1],[-13,5,1]]},spots:{shade:[20,-83,14,"the great sunshade"],icelab:[108,-6,4,"the ice lab"],ops:[94,-6,4,"the operations room"],exchange:[92,6,4,"the Caloris Exchange"],mess:[110,6,4,"the mess"],sunfield:[40,140,10,"the Sun Field"]},gather:[{k:"ow_hg_graphite",look:"dark",at:[-150,-150,55,7]},{k:"ow_hg_hollow",look:"hollow",at:[170,-150,45,7]},{k:"ow_hg_cell",look:"cell",at:[40,140,18,6]}],crew:[{id:"clerk",name:"Odile Marchetti",title:"Caloris Exchange clerk",room:"exchange",x:92,z:10,rot:Math.PI,greet:"Samples in, rations out. What have you brought me from the hollows?",who:"the clerk at the Caloris Exchange, practical and fond of a good sample"},{id:"icesci",name:"Dr Yusuf Kaya",title:"Ice lab scientist",room:"icelab",x:112,z:-8,rot:-Math.PI/2,greet:"Mind the cold case. That core came from the north pole, from a crater floor the Sun has never touched.",who:"a planetary scientist who studies the polar ice of Mercury"},{id:"tech",name:"Bea Lindqvist",title:"Solar array technician",x:40,z:128,rot:0,wander:8,greet:"The Sun Field never stops charging. Grab a full cell from a cabinet if you're helping.",who:"a solar array technician who keeps the Sun Field running"},{id:"cook",name:"Marcus Webb",title:"Station cook",room:"mess",x:111,z:10,rot:Math.PI,greet:"Hot meal? Everything here is cooked in the shade, I promise.",who:"the station cook, cheerful and generous"}],trade:{room:"exchange",at:[90,10],sells:["ow_ration","ow_pouch"],refine:"mercury",name:"The Caloris Exchange"},chal:{k:"hg_run",kind:"heat",name:"The Shadow Run",start:[74,0],about:"Seven beacons round Caloris, against the clock. Out in the sunlight your suit heats up; in shade it cools. Reach every beacon before it overheats.",beacons:[[40,80],[-50,140],[-170,60],[-170,-80],[-60,-180],[90,-120],[74,0]],shade:[[60,40],[0,110],[-110,100],[-170,-10],[-120,-130],[20,-150],[90,-60],[40,80],[-50,140],[-170,60],[-170,-80],[-60,-180],[90,-120]],heatUp:3.5,coolDown:22,max:600,min:40,reward:"ow_hg_cell"}},venus:{name:"Venus",post:"the Lavinia Control Bunker",col:"#E8A040",hall:{x:62,z:12,w:32,d:22,door:"w",name:"The Lavinia Control Bunker",rooms:[["airlock","The cold airlock",-16,-4,-8,4],["control","Rover control",-8,-11,6,-1],["exchange","The bunker store",-8,1,6,11],["workshop","The salvage workshop",6,-11,16,-1],["cooling","The cooling plant",6,1,16,11,1],["bunks","Crew bunks",-16,-11,-8,-4,1],["store","The sample store",-16,4,-8,11,1]],doors:[[-8,0],[-1,-1],[-1,1],[11,-1],[11,1,1],[-12,-4,1],[-12,4,1]]},spots:{control:[56,4,4,"rover control"],cooling:[36,24,4,"the thermometer mast"],exchange:[56,18,4,"the bunker store"]},gather:[{k:"ow_ve_basalt",look:"drill",at:[-60,40,26,5]},{k:"ow_ve_tessera",look:"tessera",at:[-55,-40,22,5]},{k:"ow_ve_salvage",look:"salvage",spots:[[-10,-60],[28,-86],[42,-54],[-74,-24],[-36,64],[44,74]]}],crew:[{id:"ctl",name:"Hana Sato",title:"Venus rover controller",room:"control",x:58,z:2,rot:Math.PI,greet:"VERA's at 465 degrees and happy. I'm at 21 and happy. Want to see what she sees?",who:"a rover controller who drives VERA from the cold rooms of the bunker"},{id:"geo",name:"Dr Emeka Obi",title:"Venus geologist",room:"workshop",x:72,z:4,rot:-Math.PI/2,greet:"Tesserae! Crumpled like a dropped tablecloth. Possibly the oldest rock on the planet.",who:"a geologist who studies the plains and tesserae of Venus"},{id:"store",name:"Ruth Abernathy",title:"Bunker storekeeper",room:"exchange",x:56,z:20,rot:Math.PI,greet:"Cold water, ration packs, and I'll rebuild salvage into parts if you bring me three.",who:"the storekeeper of the Lavinia Control Bunker"}],trade:{room:"exchange",at:[54,18],sells:["ow_ration","ow_pouch"],refine:"venus",name:"The bunker store"},chal:{k:"ve_relay",kind:"cool",name:"The Probe Relay",start:[44,12],about:"Six old probes still hold data. Reach each and press E to download it. Your suit's cooling drains all the while: top it up at the cooling posts.",beacons:[[44,74],[-36,64],[-74,-24],[-10,-60],[28,-86],[42,-54],[44,12]],posts:[[0,62],[-50,-48],[44,12]],drain:1.6,min:40,max:500,reward:"ow_ve_salvage",hold:1.5}},pluto:{name:"Pluto",post:"Tombaugh Station",col:"#C8D8F0",hall:{x:96,z:0,w:36,d:26,door:"w",name:"Tombaugh Station",rooms:[["airlock","The airlock lobby",-18,-5,-8,5],["ops","The operations room",-8,-13,6,-1],["exchange","The Exchange and cocoa bar",-8,1,6,13],["glacier","The glacier lab",6,-13,18,-1],["drill","The drill store",6,1,18,13,1],["bunks","Crew bunks",-18,-13,-8,-5,1],["heat","The heater room",-18,5,-8,13,1]],doors:[[-8,0],[-1,-1],[-1,1],[12,-1],[12,1,1],[-13,-5,1],[-13,5,1]]},spots:{ops:[94,-6,4,"the operations room"],glacier:[108,-6,4,"the glacier lab"],exchange:[92,6,4,"the Exchange"]},gather:[{k:"ow_pl_n2",look:"n2",at:[160,-200,50,7]},{k:"ow_pl_water",look:"waterice",at:[-150,-120,45,6]},{k:"ow_pl_tholin",look:"tholin",at:[-120,150,40,5]},{k:"ow_pl_methane",look:"methane",at:[200,110,35,5]}],crew:[{id:"clerk",name:"Lars Nyberg",title:"Tombaugh Exchange clerk",room:"exchange",x:92,z:10,rot:Math.PI,greet:"Cocoa's hot. Samples weighed. The two most important jobs on Pluto.",who:"the clerk at the Tombaugh Exchange, who also runs the cocoa bar"},{id:"drill",name:"Kofi Asante",title:"Ice driller",x:-150,z:-100,rot:0,wander:10,greet:"This water ice is harder than granite at minus 230. The drill earns its keep.",who:"an ice driller working the water-ice bedrock of Pluto"}],trade:{room:"exchange",at:[90,10],sells:["ow_ration","ow_cocoa","ow_pouch"],refine:"pluto",name:"The Tombaugh Exchange"},chal:{k:"pl_traverse",kind:"run",name:"The Glacier Traverse",start:[74,0],about:"Seven beacons out across the ice, over the pressure ridges. Pluto pulls only a sixteenth as hard as Earth: jump.",beacons:[[140,-80],[220,-180],[300,-290],[200,-360],[80,-300],[0,-200],[74,0]],ridges:[[180,-130,.9],[260,-235,.9],[250,-325,-.6],[140,-330,.3],[40,-250,-.8],[30,-100,.2]],min:30,max:600,reward:"ow_pl_tholin"}},jupiter:{name:"Jupiter",post:"Cloud Station Galileo",col:"#E8C89A",cloud:true,spots:{telescope:[50,-18,2.4,"the telescope at the rail"],probebay:[0,-53,4,"the probe bay"],lab:[36,20,3,"the science module"]},intakes:["ow_h2","ow_ju_ammonia","ow_h2","ow_ju_ammonia"],drop:{g:24.79,wind:3,target:"the edge of the Great Red Spot",ring:12601898},crewTitles:["Galileo probe officer","Galileo skimmer operator"]},saturn:{name:"Saturn",post:"Cloud Station Cassini",col:"#F0E0B0",cloud:true,spots:{telescope:[50,-18,2.4,"the telescope at the rail"],probebay:[0,-53,4,"the probe bay"],lab:[36,20,3,"the science module"]},intakes:["ow_h2","ow_h2","ow_h2","ow_h2"],hopper:"ow_sa_ringice",drop:{g:10.44,wind:6,target:"a storm in the bands",ring:15254138},crewTitles:["Cassini probe officer","Ring ice hauler"],tullik:true},uranus:{name:"Uranus",post:"Cloud Station Herschel",col:"#A8E0E8",cloud:true,spots:{telescope:[50,-18,2.4,"the telescope at the rail"],probebay:[0,-53,4,"the probe bay"],lab:[36,20,3,"the science module"]},intakes:["ow_h2","ow_ur_methane","ow_ur_h2s","ow_ur_methane"],drop:{g:8.69,wind:4,target:"a pale methane cloud",ring:15267071},crewTitles:["Herschel probe officer","Herschel skimmer operator"]},neptune:{name:"Neptune",post:"Cloud Station Le Verrier",col:"#8AA8F0",cloud:true,spots:{telescope:[50,-18,2.4,"the telescope at the rail"],probebay:[0,-53,4,"the probe bay"],lab:[36,20,3,"the science module"],mast:[10,-44,4,"the weather mast"]},intakes:["ow_h2","ow_ne_methane","ow_h2","ow_ne_methane"],mastGood:"ow_ne_storm",drop:{g:11.15,wind:14,target:"a dark storm",ring:1714794},crewTitles:["Le Verrier probe officer","Weather balloon launcher"]},veyar:{name:"Veyar",post:"the Veyari towers",col:"#E8B0F0",spots:{song:[-90,-80,6,"the Singing Crystals"],embassy:[70,51,5,"the Space Corp embassy"],exchange:[-70,30,7,"the Circle of Gifts"]},gather:[{k:"cr_crystal",look:"crystal",spots:[[105,-230],[-105,-230],[80,-120],[-80,-120],[140,-170],[-140,-170]]},{k:"ow_vy_glowfruit",look:"fruit",at:[130,-30,30,6]},{k:"ow_vy_dew",look:"dew",at:[-150,-20,28,6]}],crew:[{id:"envoy",name:"Envoy Celeste Morrow",title:"Envoy to Veyar",x:66,z:46,rot:Math.PI,greet:"You found the Gate. Welcome: you are one of very few. Be courteous, ask questions, and never take what is not offered.",who:"the Space Corp's envoy to the Veyari, careful, warm and diplomatic"},{id:"interp",name:"Tobias Renn",title:"Veyari interpreter",x:76,z:46,rot:Math.PI,greet:"The Veyari have eleven words for kinds of light, and none for 'mine'. Ask me anything.",who:"a Space Corp interpreter who has learned some of the Veyari language"}],trade:{at:[-70,30],sells:["ow_vy_silk"],refine:"veyar",name:"The Circle of Gifts",veyari:true},chal:{k:"vy_song",kind:"song",name:"The Crystal Song",about:"The five Singing Crystals each hold one note. Sela sings a phrase; sing it back, crystal by crystal. Each round is one note longer.",min:0,max:12,reward:"cr_crystal"}},ares:{name:"the Ares Gateway",post:"the Ares Gateway",col:"#E07A50",station:true,spots:{descent:[-8,8,3,"the descent simulator"],window:[0,-28,6,"the great window"],map:[0,-16,4,"the Mars table"],exchange:[8,-2,3,"the ore desk"],fab:[22,0,3,"the fab shop"],hydro:[-22,-10,5,"the hydroponics bay"]},gather:[{k:"ow_ar_potato",look:"hydro",spots:[[-22,-18],[-22,-8]]},{k:"ow_ar_greens",look:"hydro",spots:[[-22,-13],[-22,-3]]}],trade:{at:[8,-2],sells:["ow_ar_phobos","ow_ration","ow_pouch"],refine:"fab",name:"The Ares ore desk"},chal:{k:"ar_edl",kind:"edl",name:"The Descent Simulator",about:"Fly Perseverance's seven minutes, sped up: deploy the parachute, drop the heat shield, cut loose from the backshell and start the sky crane, each at the right moment.",min:0,max:400,reward:"ow_ar_potato"}}};var OW_GOOD={};OW_GOODS.forEach(function(e){OW_GOOD[e.k]=e});var OW_LESSON={};OW_LESSONS.forEach(function(e,t){e.n=t+1;OW_LESSON[e.k]=e});
